# Product-specific buying journeys; illustrative products, never customer case studies.
GUIDES = [
 dict(key='ebooks',name='ebooks',art='ebook-studio',icon='files',title='Your next chapter.\nTheir next download.',lead='Sell ebooks on Shopify with automatic delivery, a branded download experience and optional PDF stamping. Keep your books, bundles and customer journey together.',example='The Weekend Garden',files=['Weekend-garden.pdf','Weekend-garden.epub','Start-here.pdf'],detail='A practical gardening ebook with a readable PDF, a reflowable EPUB and a short device guide.',journey=['Choose the ebook or ebook + workbook bundle.','Complete the Shopify checkout.','Open the delivery email or post-purchase download.','Download the preferred format and start reading.'],features=[('Multiple formats','Deliver PDF and EPUB versions together and explain which one suits each device.'),('Personalised PDFs','Stamp an unprotected PDF on a paid plan to discourage casual sharing.'),('Book launches','Use scheduled delivery for a clearly announced release; test the date and timezone.')],faqs=[('Can I sell PDF and EPUB together?','Yes. Attach the files included in the offer and give each format a clear filename. PDF stamping applies to eligible PDFs, not EPUB files.'),('Can I also sell through Amazon?','Check the agreements for your title. KDP Select includes digital exclusivity during enrolment; publishing through KDP is not automatically the same as joining Select.'),('Does BIG create or edit the ebook?','No. You create the book and upload the finished files. BIG handles digital delivery after purchase.'),('Can I take ebook preorders?','Scheduled digital products support a specific release time. State the delivery date on the product page and test the setup before collecting orders.')],guide=21),
 dict(key='pdfs',name='PDFs',art='pdf-protection',icon='shield',title='Useful pages.\nBeautifully delivered.',lead='Sell PDFs on Shopify: guides, worksheets, printables and workbooks. Automate delivery and add buyer-specific stamping without handling every order yourself.',example='The Focus Workbook',files=['Focus-workbook-A4.pdf','Focus-workbook-Letter.pdf','Printing-guide.pdf'],detail='A workbook in A4 and US Letter, with printing instructions and a clear personal-use licence.',journey=['Check the preview pages and supported paper sizes.','Purchase the workbook in Shopify.','Receive access to the files; eligible PDFs can be stamped.','Choose A4 or US Letter and print at the recommended scale.'],features=[('PDF stamping','Add a deterrent to unauthorised sharing while keeping pages readable.'),('Download limits','Set reasonable access limits and retain a recovery route for real buyers.'),('Automatic delivery','Let customers retrieve the PDF without waiting for a manual attachment.')],faqs=[('Will watermarking stop all piracy?','No. Stamping discourages casual sharing but cannot prevent every copy, screenshot or removal attempt.'),('Can I stamp password-protected PDFs?','BIG’s documentation requires an unprotected PDF. Keep an original backup and test the actual customer copy.'),('Can I watermark a sample for free?','The free PDF watermark tool on this site processes a document in your browser. Purchase-specific stamping is a separate paid-plan app feature.'),('Can I sell printable PDFs?','Yes. State sizes, page count and whether the file is editable. Test a physical print before launch.')],guide=34),
 dict(key='canva-templates',name='Canva templates',art='template-studio',icon='paint',title='Your design system.\nTheir creative head start.',lead='Sell Canva templates on Shopify with a clear, automated handoff. Deliver a PDF containing the template link, setup instructions and the licence buyers need.',example='The Small Studio Social Kit',files=['Start-here.pdf','Template-access.pdf','Licence.pdf'],detail='A coordinated social template collection, delivered through a welcome PDF that links to the buyer’s own copy in Canva.',journey=['Preview the layouts and check Canva account requirements.','Buy the template pack through Shopify.','Download the welcome PDF and open the template link.','Create a personal copy in Canva, customise and export.'],features=[('Files and access links','Deliver the welcome PDF and access instructions in one purchase.'),('Branded handoff','Match the delivery experience to the visual identity of your studio.'),('Custom design orders','Use custom delivery for work that must be created after the order.')],faqs=[('Do buyers need Canva Pro?','That depends on your template’s assets and functions. Test with a separate free account and disclose any paid requirements before purchase.'),('Should I share my editable master?','Use Canva’s template-sharing workflow so each customer works on a copy. Test the link while signed out or using another account.'),('Does BIG control access inside Canva?','No. BIG delivers your files or links. Canva permissions and the template link’s sharing behaviour remain separate.'),('May I resell any Canva template?','No. Create an original product and check Canva’s current content licence. A subscription is not blanket permission to resell library content.')],guide=19),
 dict(key='license-keys',name='license keys',art='license-studio',icon='key',title='One purchase.\nOne key. Zero copy-paste.',lead='Sell license keys on Shopify and deliver the right code with the right product. Organise your key inventory and test fulfilment before your next launch.',example='Studio Tools · Pro licence',files=['Your unique licence key','Activation-guide.pdf','Download link'],detail='A software licence with a unique key, the installer link and instructions for activating the correct edition.',journey=['Select the product edition or licence tier.','Complete checkout with the correct variant.','Receive the assigned key and activation instructions.','Activate in your software or licensing service.'],features=[('Key delivery','Connect your licence inventory to the appropriate digital product.'),('Files + keys','Make the installer, key and instructions part of a clear delivery journey.'),('Operational control','Export keys and orders; use API and outgoing webhooks on Growth or Enterprise.')],faqs=[('Does BIG validate or revoke software activations?','Key delivery and software activation are different systems. Your application or licensing provider must handle validation, device limits and revocation.'),('Can I deliver a file with a key?','BIG supports files and licence keys. Test your exact product and variant setup so the correct edition reaches the buyer.'),('What if my key inventory runs out?','Plan inventory monitoring and test the app’s behaviour before launch. Do not promise unlimited availability without replenishment.'),('Can I sell third-party game keys?','Only distribute keys you are authorised to sell. Check the publisher’s terms, region restrictions and Shopify’s applicable rules.')],guide=15),
 dict(key='software',name='software',art='software-studio',icon='code',title='Ship your software.\nOwn the release.',lead='Sell software on Shopify with organised installers, automatic file delivery and licence keys. Give customers a clear path from purchase to installation.',example='Studio Tools · Desktop app',files=['StudioTools-macOS-v1.2.zip','StudioTools-Windows-v1.2.zip','Install-and-activate.pdf'],detail='A desktop utility with platform-specific downloads, release notes and a separate activation service where required.',journey=['Check supported operating systems and choose an edition.','Pay through Shopify.','Download the matching installer and any included key.','Follow the setup guide and contact your support team if needed.'],features=[('Product and variant mapping','Keep editions and operating-system files clearly separated.'),('Licence keys','Deliver keys while your own system handles activation enforcement.'),('API and webhooks','Integrate delivery operations with your tools on Growth or Enterprise.')],faqs=[('Does BIG host my SaaS application?','No. It delivers files, links and keys. Application hosting, accounts, subscriptions and activation services are separate.'),('Can I distribute Windows and macOS builds?','Yes. Name builds clearly and test each product or variant with its intended operating system.'),('Does BIG code-sign installers?','No. Use the appropriate signing and distribution process for your platform before uploading the release.'),('Can I deliver software updates?','Plan how existing customers receive access to new versions and test that workflow. State the update entitlement in your licence.')],guide=31),
 dict(key='music',name='music',art='audio-studio',icon='download',title='Made to be heard.\nReady to be sold.',lead='Sell music on Shopify: albums, sample packs, sound effects and audio lessons. Deliver MP3, WAV or FLAC files with clear formats and licensing information.',example='After Hours · Sample pack',files=['After-hours-WAV.zip','Preview-mix.mp3','Licence-and-readme.pdf'],detail='An original sample collection with labelled audio files, a preview and explicit permitted uses.',journey=['Listen to a preview and check the included formats.','Choose the pack or licence tier and pay.','Receive the download link by email or after checkout.','Download, extract and use the audio within the licence.'],features=[('Multi-file products','Keep tracks, stems, artwork and the readme together.'),('Scheduled releases','Coordinate access with a specific album or pack release date.'),('Capacity choices','Choose storage and bandwidth for the formats and download volumes you expect.')],faqs=[('Can I sell WAV and FLAC files?','BIG supports digital file delivery. State the exact audio formats you provide and test playback on the devices you advertise.'),('Is this a music streaming service?','This page describes downloadable audio delivery. Do not assume subscription streaming, playlists or music-platform distribution are included.'),('Can I sell stems or sample packs?','Yes, for content you have the right to distribute. Label tempo, key and format when relevant and include a clear licence.'),('What plan suits large audio packs?','Estimate stored GB and monthly transferred GB separately. A 500 MB pack downloaded 1,000 times uses about 500 GB before retries.')],guide=25),
 dict(key='videos',name='videos',art='video-studio',icon='files',title='Press play on\nyour next business.',lead='Sell downloadable videos on Shopify with a clear purchase and delivery experience. Package workshops, tutorials and original footage alongside useful companion files.',example='The Weekend Filmmaker Workshop',files=['01-Getting-started.mp4','02-Shooting-with-intent.mp4','Workshop-transcript.pdf'],detail='A compact video workshop with numbered lessons, transcripts and a printable exercise sheet.',journey=['Watch a preview and check duration, format and file sizes.','Purchase through Shopify.','Open the delivery page and choose the lesson files.','Download and watch in a compatible player.'],features=[('Organised downloads','Use lesson names and companion documents that make the starting point obvious.'),('Large-file planning','Choose capacity around total file size and expected repeat downloads.'),('Scheduled access','Use a defined release time for a workshop launch or video premiere download.')],faqs=[('Is protected streaming included?','This page is about file delivery. If you need a streaming-first experience or subscription access controls, verify those requirements separately before choosing an app.'),('How much bandwidth do videos use?','A 2 GB workshop downloaded 300 times transfers roughly 600 GB, before retries and extra formats. Use realistic viewing and download assumptions.'),('Can I add subtitles or transcripts?','Include the compatible subtitle or transcript files you have prepared, and explain how buyers use them.'),('Can buyers watch on mobile?','That depends on file format, size, player and available space. Test the actual files on a phone and describe the requirements.')],guide=27),
 dict(key='digital-art',name='digital art',art='art-studio',icon='paint',title='Your original work.\nA whole new audience.',lead='Sell digital art on Shopify, from downloadable prints to custom commissions. Deliver finished files with the right dimensions, formats and usage licence.',example='Soft Shapes · Art print set',files=['Soft-shapes-2x3.jpg','Soft-shapes-A-series.pdf','Print-and-licence-guide.pdf'],detail='An original printable artwork in labelled ratios, with guidance on printing and personal-use rights.',journey=['Preview the art and choose a format or commission.','Purchase with clear delivery timing.','Receive an instant file or the finished custom artwork later.','Download the appropriate size and follow the print guidance.'],features=[('Instant and custom products','Separate ready-made artwork from pieces you create after purchase.'),('Organised file sets','Label print ratios and file formats so customers choose correctly.'),('Branded presentation','Keep the handoff consistent with your portfolio and store.')],faqs=[('Can I sell personalised portraits?','Custom digital products are designed for made-to-order work. State your input requirements, turnaround and revision scope clearly.'),('Do I need to ship a physical print?','No for a download-only offer. Say clearly that the purchase contains digital files and no physical item will ship.'),('Does a download transfer copyright?','Not automatically. Explain the rights you grant in your licence and only sell work you are authorised to distribute.'),('What resolution should I offer?','Choose dimensions for the advertised print sizes and test a print. Pixel dimensions matter more than changing the DPI metadata alone.')],guide=18),
 dict(key='online-courses',name='online courses',art='video-studio',icon='calendar',title='Teach what you know.\nDeliver a clear next step.',lead='Sell self-guided online courses on Shopify as video lessons, workbooks and access links. Make the learning journey clear from checkout to the first exercise.',example='The Creative Business Starter Course',files=['00-Start-here.pdf','01-Your-first-offer.mp4','Exercises-and-transcripts.zip'],detail='A self-guided course with a contents guide, numbered video lessons and practical exercises.',journey=['Review the syllabus, level and delivery format.','Buy the course in Shopify.','Open the start-here guide from the delivery page.','Follow the lesson sequence at your own pace.'],features=[('Course file delivery','Package video, PDF and supporting files into an organised offer.'),('Fixed-date launches','Schedule a product release at an announced date and time.'),('Support-ready operations','Resend delivery messages and help learners recover access.')],faqs=[('Is BIG a complete learning management system?','No full LMS is claimed here. Progress tracking, grading, quizzes and certificates require a dedicated platform or separately verified integration.'),('Can I drip a lesson each week after each purchase?','A fixed scheduled release is not the same as a per-student drip schedule. Verify the exact workflow before advertising it.'),('Can I include an external course access link?','BIG can deliver access links. The external platform must manage its own accounts, permissions and access lifecycle.'),('When should I use an LMS instead?','Choose an LMS when learner progress, assessments, certificates, cohorts or streaming controls are essential. BIG fits a clear file-based learning product.')],guide=27)
]
